<script>document.addEventListener('DOMContentLoaded',function(){const vehicle=document.getElementById('vehicle_id'),plateHeader=document.getElementById('vehicle-plate-header'),plate=document.getElementById('vehicle-plate-value'),fuel=document.getElementById('fuel_type_id'),requester=document.getElementById('requester_person_id'),requesterName=document.getElementById('requester_name'),requesterHelp=document.getElementById('requester-help'),sectorField=document.getElementById('sector-field'),sector=document.getElementById('responsible_sector'),odometer=document.getElementById('odometer'),liters=document.getElementById('requested_liters'),amount=document.getElementById('estimated_amount'),unitPrice=document.getElementById('reference_unit_price'),status=document.getElementById('vehicle-guidance'),priceLabel=document.getElementById('reference-price'),prices=@json($referencePrices);const currency=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});const currentReference=()=>prices[String(fuel.value)]??null;const currentPrice=()=>Number(currentReference()?.value??0);function showPrice(){const ref=currentReference(),price=currentPrice();unitPrice.value=price>0?price.toFixed(3):'';priceLabel.textContent=price>0?'Última vigência: '+ref.effective_at+' · '+currency.format(price)+' por litro.':'Sem preço de referência disponível para este combustível.'}function calculate(){const price=currentPrice(),quantity=Number(liters.value);if(price>0&&Number.isFinite(quantity)&&quantity>=0)amount.value=(price*quantity).toFixed(2)}function sectors(choice){try{return JSON.parse(choice.dataset.sectors||'[]')}catch{return[]}}function applyVehicle(){const choice=vehicle.options[vehicle.selectedIndex];if(!vehicle.value){plate.textContent='—';fuel.value='';requester.value='';requesterName.value='';requesterHelp.textContent='Preenchido automaticamente pelo responsável vinculado ao veículo.';odometer.value='';sector.innerHTML='<option value="">Selecione um setor responsável</option>';sectorField.style.display='none';sector.required=false;showPrice();status.textContent='Selecione o veículo para carregar os dados.';return}plate.textContent=(choice.textContent||'').split('·')[0].trim();fuel.value=choice.dataset.fuelTypeId||'';requester.value=choice.dataset.requesterId||'';odometer.value=choice.dataset.odometer||'';const options=sectors(choice);sector.innerHTML='<option value="">Selecione um setor responsável</option>'+options.map(item=>'<option value="'+String(item).replace(/"/g,'&quot;')+'">'+item+'</option>').join('');const hasCouncil=Boolean(requester.value);if(hasCouncil){requesterName.value=choice.dataset.requesterName;requesterHelp.textContent='Vereador responsável preenchido automaticamente.';sectorField.style.display='none';sector.required=false;status.textContent='Vereador responsável carregado. Confirme combustível e hodômetro antes de salvar.'}else if(options.length===1){requesterName.value=options[0];requesterHelp.textContent='Setor responsável preenchido automaticamente.';sector.value=options[0];sectorField.style.display='none';sector.required=false;status.textContent='Setor responsável carregado. Confirme combustível e hodômetro antes de salvar.'}else{requesterName.value='Selecione um dos setores responsáveis';requesterHelp.textContent='O veículo é compartilhado por mais de um setor.';sectorField.style.display='grid';sector.required=true;if(sector.dataset.oldSector)sector.value=sector.dataset.oldSector;status.textContent='Selecione o setor responsável para continuar.'}showPrice();calculate()}vehicle.addEventListener('change',applyVehicle);fuel.addEventListener('change',()=>{showPrice();calculate()});liters.addEventListener('input',calculate);if(vehicle.value)applyVehicle()});</script>
